UPDATE page_blocks
SET props_json = '{"html":"<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\r\n    <!-- Bypasses Taplink/external server image blocking -->\r\n    <meta name=\"referrer\" content=\"no-referrer\">\r\n    \r\n    <title>& Other Stories — Shop</title>\r\n    <link rel=\"icon\" href=\"favicon.svg\" type=\"image/svg+xml\">\r\n    <link rel=\"apple-touch-icon\" href=\"favicon.svg\">\r\n    <!-- Tailwind CSS for styling -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <!-- Editorial typography aligned with stories.com -->\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=Outfit:wght@300;400;500;600&display=swap\" rel=\"stylesheet\">\r\n    <!-- Lucide Icons -->\r\n    <script src=\"https://unpkg.com/lucide@0.469.0/dist/umd/lucide.min.js\"></script>\r\n\r\n    <style>\r\n        :root {\r\n            --os-bg: #faf8f6;\r\n            --os-surface: #ffffff;\r\n            --os-ink: #1a1a1a;\r\n            --os-muted: #6b6560;\r\n            --os-border: #e8e5e1;\r\n            --os-sale: #8b4049;\r\n        }\r\n        body {\r\n            font-family: ''Outfit'', system-ui, sans-serif;\r\n            background-color: var(--os-bg);\r\n            color: var(--os-ink);\r\n            -webkit-font-smoothing: antialiased;\r\n            overflow-x: hidden;\r\n            position: relative;\r\n        }\r\n        .font-display {\r\n            font-family: ''Cormorant Garamond'', Georgia, ''Times New Roman'', serif;\r\n        }\r\n        .os-btn-primary {\r\n            background-color: var(--os-ink);\r\n            color: #fff;\r\n        }\r\n        .os-btn-primary:hover {\r\n            opacity: 0.9;\r\n        }\r\n        .os-nav-link {\r\n            color: var(--os-muted);\r\n        }\r\n        .os-nav-link:hover {\r\n            color: var(--os-ink);\r\n        }\r\n        #desktop-nav-links a {\r\n            letter-spacing: 0.08em;\r\n        }\r\n        \r\n        ::-webkit-scrollbar { width: 4px; }\r\n        ::-webkit-scrollbar-track { background: transparent; }\r\n        ::-webkit-scrollbar-thumb { background: #d4cfc8; border-radius: 10px; }\r\n\r\n        .hide-scroll::-webkit-scrollbar { display: none; }\r\n        .hide-scroll { -ms-overflow-style: none; scrollbar-width: none; }\r\n\r\n        .product-image-container {\r\n            aspect-ratio: 3 / 4;\r\n            overflow: hidden;\r\n            position: relative;\r\n            background-color: #f0ebe6;\r\n        }\r\n        \r\n        .product-image {\r\n            width: 100%;\r\n            height: 100%;\r\n            object-fit: cover;\r\n            transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.4s ease-in-out;\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            will-change: opacity, transform;\r\n        }\r\n        \r\n        @media (hover: hover) {\r\n            .product-card:hover .product-image {\r\n                transform: scale(1.05);\r\n            }\r\n        }\r\n\r\n        #toast {\r\n            transition: opacity 0.3s ease, transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);\r\n            opacity: 0;\r\n            transform: translate(-50%, 20px);\r\n            pointer-events: none;\r\n        }\r\n        #toast.show {\r\n            opacity: 1;\r\n            transform: translate(-50%, 0);\r\n            pointer-events: auto;\r\n        }\r\n\r\n        button, a {\r\n            min-height: 44px;\r\n            display: inline-flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            user-select: none;\r\n            -webkit-tap-highlight-color: transparent;\r\n        }\r\n\r\n        .size-btn {\r\n            min-height: 34px;\r\n            padding: 0.45rem 0.75rem;\r\n            background: transparent;\r\n            color: var(--os-ink);\r\n            border-color: var(--os-border);\r\n            letter-spacing: 0.14em;\r\n            transition: border-color 180ms ease, background-color 180ms ease, color 180ms ease, opacity 180ms ease;\r\n        }\r\n        .size-btn:hover {\r\n            border-color: var(--os-ink);\r\n        }\r\n        .size-btn:focus-visible {\r\n            outline: none;\r\n            box-shadow: 0 0 0 2px rgba(26,26,26,0.12);\r\n        }\r\n        .os-size-selected {\r\n            background-color: var(--os-ink) !important;\r\n            color: #fff !important;\r\n            border-color: var(--os-ink) !important;\r\n        }\r\n        .os-size-oos {\r\n            opacity: 0.45;\r\n            text-decoration: line-through;\r\n            cursor: not-allowed;\r\n        }\r\n        .os-size-oos:hover {\r\n            border-color: var(--os-border);\r\n        }\r\n        \r\n        .animate-fade-in {\r\n            animation: fadeIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;\r\n        }\r\n        @keyframes fadeIn {\r\n            from { opacity: 0; transform: translateY(8px); }\r\n            to { opacity: 1; transform: translateY(0); }\r\n        }\r\n\r\n        .mobile-cat-nav {\r\n            display: flex;\r\n            overflow-x: auto;\r\n            white-space: nowrap;\r\n            -webkit-overflow-scrolling: touch;\r\n            padding-bottom: 4px;\r\n        }\r\n    </style>\r\n</head>\r\n<body class=\"flex flex-col min-h-screen relative\" style=\"background-color: var(--os-bg); color: var(--os-ink);\">\r\n\r\n    <!-- Top Banner (controlled by Settings) -->\r\n    <div id=\"top-banner\" class=\"hidden w-full border-b\" style=\"background-color: rgba(255,255,255,0.7); border-color: var(--os-border);\">\r\n        <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-2 flex items-center justify-center gap-3\">\r\n            <span id=\"top-banner-text\" class=\"text-[10px] uppercase tracking-widest\" style=\"color: var(--os-muted);\"></span>\r\n            <a id=\"top-banner-link\" class=\"hidden text-[10px] uppercase tracking-widest underline\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--os-ink);\"></a>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- Navigation Bar -->\r\n    <nav class=\"sticky top-0 z-50 backdrop-blur-xl border-b\" style=\"background-color: rgba(250,248,246,0.92); border-color: var(--os-border);\">\r\n        <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\r\n            <div class=\"flex items-center min-h-16 sm:min-h-20 py-2 gap-1 sm:gap-2\">\r\n                <!-- Left: category links (desktop), mirrors stories.com shop nav -->\r\n                <div class=\"hidden md:flex flex-1 min-w-0 flex-wrap items-center gap-x-1 gap-y-1 pr-2\" id=\"desktop-nav-links\"></div>\r\n                <div class=\"flex md:hidden flex-1 min-w-[2rem] shrink\" aria-hidden=\"true\"></div>\r\n\r\n                <!-- Center: wordmark -->\r\n                <div class=\"flex-shrink-0 flex items-center justify-center cursor-pointer px-2\" onclick=\"forceRefreshData()\">\r\n                    <a href=\"#\" class=\"inline-flex items-center justify-center text-center text-lg sm:text-xl font-display font-medium tracking-wide text-[#1a1a1a]\" id=\"brand-name\">&amp; Other Stories</a>\r\n                </div>\r\n\r\n                <!-- Right: search + bag (stories-style labels on wide screens) -->\r\n                <div class=\"flex flex-1 justify-end items-center min-w-0 gap-0 sm:gap-1 pl-2\">\r\n                    <a href=\"#shop\" class=\"p-2 os-nav-link flex items-center gap-2 text-[11px] uppercase tracking-[0.12em]\" id=\"nav-search-icon\">\r\n                        <i data-lucide=\"search\" class=\"w-[18px] h-[18px] sm:w-5 sm:h-5 shrink-0\"></i>\r\n                        <span class=\"hidden xl:inline pt-0.5 font-medium\">Search</span>\r\n                    </a>\r\n                    <a href=\"#cart\" class=\"p-2 os-nav-link relative flex items-center gap-2 text-[11px] uppercase tracking-[0.12em]\" id=\"nav-bag-link\">\r\n                        <i data-lucide=\"shopping-bag\" class=\"w-[18px] h-[18px] sm:w-5 sm:h-5 shrink-0\"></i>\r\n                        <span class=\"hidden xl:inline pt-0.5 font-medium\">Bag</span>\r\n                        <span id=\"cart-badge\" class=\"absolute top-1 right-0.5 xl:top-1.5 xl:right-1 inline-flex items-center justify-center min-w-[1.125rem] h-[1.125rem] px-0.5 text-[9px] font-bold leading-none text-white rounded-full hidden\" style=\"background-color: var(--os-ink);\">0</span>\r\n                    </a>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <!-- Mobile Category Nav -->\r\n        <div class=\"md:hidden border-t px-4 py-2\" style=\"border-color: var(--os-border); background-color: rgba(255,255,255,0.5);\">\r\n            <div class=\"mobile-cat-nav hide-scroll space-x-6 text-[11px] font-medium uppercase tracking-widest\" id=\"mobile-nav-links\">\r\n                <!-- Nav links injected dynamically -->\r\n            </div>\r\n        </div>\r\n    </nav>\r\n\r\n    <!-- Main content: first route paints immediately; no long “Loading shop…” copy (skeleton used when catalog is empty). -->\r\n    <main id=\"app-content\" class=\"flex-grow w-full max-w-7xl mx-auto focus:outline-none\" aria-live=\"polite\">\r\n        <div id=\"app-boot-hint\" class=\"hidden\" aria-hidden=\"true\"></div>\r\n    </main>\r\n\r\n    <!-- Footer -->\r\n    <footer class=\"border-t py-12 px-4 mt-auto\" style=\"background-color: var(--os-surface); border-color: var(--os-border);\">\r\n        <div class=\"max-w-7xl mx-auto text-center text-[10px] uppercase tracking-widest space-y-2\" style=\"color: var(--os-muted);\">\r\n            <p>&copy; <span id=\"current-year\"></span> <span class=\"brand-name-text\"></span></p>\r\n            <p style=\"color: #b0aaa4;\">All rights reserved</p>\r\n        </div>\r\n    </footer>\r\n\r\n    <!-- Fullscreen Lightbox -->\r\n    <div id=\"lightbox\" class=\"fixed inset-0 z-[100] bg-black hidden flex-col transition-opacity opacity-0 duration-300\">\r\n        <div class=\"flex justify-between items-center p-4 text-white absolute top-0 w-full z-10 bg-gradient-to-b from-black/50 to-transparent\">\r\n            <span id=\"lightbox-counter\" class=\"text-xs tracking-widest uppercase\">1 / 1</span>\r\n            <button onclick=\"closeLightbox()\" class=\"p-2 text-white/80 hover:text-white\"><i data-lucide=\"x\" class=\"w-6 h-6\"></i></button>\r\n        </div>\r\n        <div class=\"flex-1 relative flex items-center justify-center overflow-hidden\" id=\"lightbox-touch-area\">\r\n            <img id=\"lightbox-img\" src=\"data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=\" class=\"w-full h-auto max-h-screen object-contain transition-transform duration-300 cursor-zoom-in\" onclick=\"toggleLightboxZoom()\">\r\n            <button id=\"lb-prev\" onclick=\"changeLightboxImage(-1)\" class=\"absolute left-4 p-3 text-white/80 hover:text-white hidden\"><i data-lucide=\"chevron-left\" class=\"w-8 h-8 drop-shadow-lg\"></i></button>\r\n            <button id=\"lb-next\" onclick=\"changeLightboxImage(1)\" class=\"absolute right-4 p-3 text-white/80 hover:text-white hidden\"><i data-lucide=\"chevron-right\" class=\"w-8 h-8 drop-shadow-lg\"></i></button>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- Toast Notification -->\r\n    <div id=\"toast\" class=\"fixed bottom-8 left-1/2 -translate-x-1/2 text-white px-6 py-3.5 rounded-full shadow-2xl z-50 text-xs font-medium flex items-center space-x-3 whitespace-nowrap z-[100]\" style=\"background-color: var(--os-ink);\">\r\n        <i data-lucide=\"check\" class=\"w-4 h-4 text-green-400\"></i>\r\n        <span id=\"toast-msg\">Success</span>\r\n    </div>\r\n\r\n    <script>\r\n        const MAIN_IMAGES = {\r\n            heroLeft: \"https://pub-be47a8b9e3174a41b2fe163b4ca48e2c.r2.dev/IM_26_14_012_16x9_mid_res_srgb.jpg?imwidth=700\",\r\n            heroRight: \"https://pub-be47a8b9e3174a41b2fe163b4ca48e2c.r2.dev/IM_26_14_011_5x7.jpg?imwidth=1200\",\r\n            categoryWomen: \"https://pub-be47a8b9e3174a41b2fe163b4ca48e2c.r2.dev/IM_26_14_001_5x7_mid_res_srgb.jpg?imwidth=1200\"\r\n        };\r\n\r\n        /** Single source of truth for shop/home/nav after eligibility + image checks. */\r\n        let VISIBLE_PRODUCTS = [];\r\n\r\n        /** Preferred category labels — nav shows these first when present; other sheet labels still work. */\r\n        const ALLOWED_CATEGORIES = [''Clothing'', ''Accessories'', ''Swimwear & Socks'', ''Shoes'', ''Beauty'', ''Press''];\r\n\r\n        /** Common Google Sheet variants → canonical name */\r\n        const CATEGORY_ALIASES = {\r\n            ''women'': ''Clothing'',\r\n            ''womens'': ''Clothing'',\r\n            \"women''s\": ''Clothing'',\r\n            ''woman'': ''Clothing'',\r\n            ''female'': ''Clothing'',\r\n            ''accessor'': ''Accessories'',\r\n            ''accessory'': ''Accessories'',\r\n            ''bags'': ''Accessories'',\r\n            ''bag'': ''Accessories'',\r\n            ''lingerie'': ''Swimwear & Socks'',\r\n            ''lingerie & socks'': ''Swimwear & Socks'',\r\n            ''socks'': ''Swimwear & Socks'',\r\n            ''swim'': ''Swimwear & Socks'',\r\n            ''swimwear'': ''Swimwear & Socks'',\r\n            ''shoe'': ''Shoes'',\r\n            ''footwear'': ''Shoes'',\r\n            ''makeup'': ''Beauty'',\r\n            ''cosmetics'': ''Beauty'',\r\n            ''press'': ''Press''\r\n        };\r\n\r\n        function normalizeCategory(cat) {\r\n            if (cat == null) return null;\r\n            const s = String(cat).trim();\r\n            if (!s) return null;\r\n            const lower = s.toLowerCase();\r\n            if (CATEGORY_ALIASES[lower]) return CATEGORY_ALIASES[lower];\r\n            for (let i = 0; i < ALLOWED_CATEGORIES.length; i++) {\r\n                if (ALLOWED_CATEGORIES[i].toLowerCase() === lower) return ALLOWED_CATEGORIES[i];\r\n            }\r\n            return null;\r\n        }\r\n\r\n        /** Like the old catalog: unknown or blank category still gets a label so the row is not dropped. */\r\n        function resolveCategoryForProduct(p) {\r\n            const n = normalizeCategory(p.category);\r\n            if (n) return n;\r\n            const s = p.category != null ? String(p.category).trim() : '''';\r\n            if (s) return s;\r\n            return ''Clothing'';\r\n        }\r\n\r\n        /** Blank status = treat as active (matches most sheets that omit the column). */\r\n        function isProductActive(p) {\r\n            if (p == null) return false;\r\n            if (p.status === undefined || p.status === null || String(p.status).trim() === '''') return true;\r\n            if (p.status === true) return true;\r\n            const s = String(p.status).trim().toLowerCase();\r\n            if (s === ''inactive'' || s === ''false'' || s === ''0'' || s === ''no'' || s === ''disabled'') return false;\r\n            return s === ''active'' || s === ''1'' || s === ''yes'' || s === ''true'';\r\n        }\r\n\r\n        /** Blank/missing stock = in stock (old behavior). Only 0 explicitly hides. */\r\n        function getStockQty(p) {\r\n            const raw = p.stock != null ? p.stock : (p.qty != null ? p.qty : p.quantity);\r\n            if (raw === undefined || raw === null || String(raw).trim() === '''') return 999;\r\n            const n = parseInt(raw, 10);\r\n            return isNaN(n) ? 999 : n;\r\n        }\r\n\r\n        function isSaleTag(p) {\r\n            const t = p && (p.tag != null ? p.tag : p.saleTag);\r\n            return t != null && String(t).trim().toUpperCase() === ''SALE'';\r\n        }\r\n\r\n        function isAuraProduct(p) {\r\n            const match = String(CONFIG.auraTypeMatchText || ''AURA'').trim().toLowerCase();\r\n            if (!match) return false;\r\n            const st = p && p.saleType != null ? String(p.saleType).toLowerCase() : '''';\r\n            const tg = p && (p.saleTag != null ? String(p.saleTag) : (p.tag != null ? String(p.tag) : '''')).toLowerCase();\r\n            return (st && st.includes(match)) || (tg && tg.includes(match));\r\n        }\r\n\r\n        function getCampaignTag(p) {\r\n            const t = p && (p.tag != null ? p.tag : p.saleTag);\r\n            const s = t == null ? '''' : String(t).trim();\r\n            return s;\r\n        }\r\n\r\n        function isClothingCategory_(cat) {\r\n            const c = String(cat || '''').trim();\r\n            return c === ''Women'' || c === ''Men'' || c === ''Clothing'';\r\n        }\r\n\r\n        function monthTagOrderList() {\r\n            const raw = String(CONFIG.monthTagOrder || '''').trim();\r\n            const def = \"May, April, March, February, January, 0\";\r\n            const src = raw || def;\r\n            return src.split('','').map(function (x) { return String(x || '''').trim(); }).filter(Boolean);\r\n        }\r\n\r\n        function monthTagRank(tag, orderList) {\r\n            const t = String(tag || '''').trim().toLowerCase();\r\n            if (!t) return orderList.length + 999;\r\n            for (let i = 0; i < orderList.length; i++) {\r\n                if (String(orderList[i]).trim().toLowerCase() === t) return i;\r\n            }\r\n            return orderList.length + 999;\r\n        }\r\n\r\n        function isBackgroundMonthTag_(tag) {\r\n            const t = String(tag || '''').trim();\r\n            if (!t) return false;\r\n            const low = t.toLowerCase();\r\n            // Use Settings-defined month order (plus defaults) as the canonical list of hidden background tags.\r\n            const list = monthTagOrderList();\r\n            for (let i = 0; i < list.length; i++) {\r\n                if (String(list[i] || '''').trim().toLowerCase() === low) return true;\r\n            }\r\n            // Safety net in case monthTagOrder is blank/missing.\r\n            const months = [''january'',''february'',''march'',''april'',''may'',''june'',''july'',''august'',''september'',''october'',''november'',''december'',''0''];\r\n            return months.includes(low);\r\n        }\r\n\r\n        function getCategoryHeroImage(cat) {\r\n            if (cat === ''Clothing'' && CONFIG.categoryWomenImage && String(CONFIG.categoryWomenImage).trim()) {\r\n                return String(CONFIG.categoryWomenImage).trim();\r\n            }\r\n            return MAIN_IMAGES.categoryWomen;\r\n        }\r\n\r\n        function getSubcategory(p) {\r\n            // First check if your sheet has these columns explicitly\r\n            if (p.subcategory) return String(p.subcategory).trim();\r\n            if (p.sub_category) return String(p.sub_category).trim();\r\n            if (p.type) return String(p.type).trim();\r\n            \r\n            // If not, automatically group them based on keywords in the product name!\r\n            const n = String(p.name || '''').toLowerCase();\r\n            if (n.includes(''dress'')) return ''Dresses'';\r\n            if (n.includes(''top'') || n.includes(''shirt'') || n.includes(''blouse'') || n.includes(''tee'')) return ''Tops'';\r\n            if (n.includes(''knit'') || n.includes(''sweater'') || n.includes(''cardigan'') || n.includes(''jumper'') || n.includes(''pullover'')) return ''Knitwear'';\r\n            if (n.includes(''trouser'') || n.includes(''pant'') || n.includes(''jean'') || n.includes(''legging'')) return ''Trousers'';\r\n            if (n.includes(''skirt'')) return ''Skirts'';\r\n            if (n.includes(''jacket'') || n.includes(''coat'') || n.includes(''blazer'') || n.includes(''vest'')) return ''Outerwear'';\r\n            if (n.includes(''short'')) return ''Shorts'';\r\n            if (n.includes(''swim'') || n.includes(''bikini'') || n.includes(''swimsuit'')) return ''Swimwear'';\r\n            \r\n            return ''Other'';\r\n        }\r\n\r\n        /** Categories for nav: preferred order first, then any other labels present in data. */\r\n        function getCategoriesPresentInVisible() {\r\n            const set = new Set();\r\n            VISIBLE_PRODUCTS.forEach(function (p) {\r\n                if (p.category) set.add(p.category);\r\n            });\r\n            const ordered = ALLOWED_CATEGORIES.filter(function (c) { return set.has(c); });\r\n            const rest = Array.from(set).filter(function (c) {\r\n                return ALLOWED_CATEGORIES.indexOf(c) === -1;\r\n            }).sort();\r\n            return ordered.concat(rest);\r\n        }\r\n\r\n        const escapeHTML = (str) => {\r\n            if (!str) return '''';\r\n            return String(str).replace(/[&<>''\"]/g, match => ({\r\n                ''&'': ''&amp;'', ''<'': ''&lt;'', ''>'': ''&gt;'', \"''\": ''&#39;'', ''\"'': ''&quot;''\r\n            })[match]);\r\n        };\r\n\r\n        const FILE_BRAND_NAME = \"& Other Stories\";\r\n        const FILE_BRAND_LOGO = \"https://logos-world.net/wp-content/uploads/2025/10/Other-Stories-Logo-New.png\";\r\n\r\n        /** Sheet sample data often still says \"COS\"; ignore so tab title + logo stay & Other Stories. */\r\n        const purgeLegacyCosBranding = () => {\r\n            try {\r\n                const n = typeof CONFIG.brandName === ''string'' ? CONFIG.brandName.trim() : '''';\r\n                if (/^cos$/i.test(n)) {\r\n                    CONFIG.brandName = FILE_BRAND_NAME;\r\n                    CONFIG.brandLogoUrl = FILE_BRAND_LOGO;\r\n                    return;\r\n                }\r\n                const u = String(CONFIG.brandLogoUrl || '''').toLowerCase();\r\n                if (u.includes(''cos.com'') || u.includes(''cosstores'')) {\r\n                    CONFIG.brandLogoUrl = FILE_BRAND_LOGO;\r\n                }\r\n            } catch (e) {}\r\n        };\r\n\r\n        // Cache Reset\r\n        (function cleanOldCaches() {\r\n            try {\r\n                for (let i = 0; i < localStorage.length; i++) {\r\n                    const key = localStorage.key(i);\r\n                    if (key === ''os_settings_v10'') {\r\n                        localStorage.removeItem(key);\r\n                        continue;\r\n                    }\r\n                    if (key && (key.startsWith(''cos_'') || key.startsWith(''os_'') || key.startsWith(''fashion_cart''))) {\r\n                        // Keep only current cache versions; remove older ones automatically.\r\n                        if (!key.includes(''v10'') && !key.includes(''v11'') && !key.includes(''v12'') && !key.includes(''v13'') && !key.includes(''v14'') && !key.includes(''v15'') && !key.includes(''v16'')) localStorage.removeItem(key);\r\n                    }\r\n                }\r\n            } catch (e) {}\r\n        })();\r\n\r\n        const CONFIG = {\r\n            // Site branding stays fixed to the file constants (do not override from sheet settings).\r\n            brandName: FILE_BRAND_NAME,\r\n            brandLogoUrl: FILE_BRAND_LOGO,\r\n            /** Optional: shown only inside the cart \"Order summary\" card. */\r\n            cartStoreName: \"\",\r\n            heroImage: \"\",\r\n            categoryWomenImage: \"\",\r\n            categoryMenImage: \"\",\r\n            enableWhatsAppOrder: true,\r\n            whatsappNumber: \"97317369579\", \r\n            currency: \"AED\",\r\n            googleSheetWebAppUrl: \"https://script.google.com/macros/s/AKfycbwZKIbIFvEuFp1KWqsKb3Nmi3J0aP6cC6MZrGJXd1KGxHRsGMmsTLc_acZDd8SaG6XVzA/exec\",\r\n            /**\r\n             * Cloudflare Worker in front of the same web app: edge caching + often faster first byte than cold GAS.\r\n             * Leave \"\" to talk to Apps Script only. If the worker errors, the page sets window.__forceDirectCatalog and falls back.\r\n             */\r\n            catalogApiUrl: \"https://os-catalog-proxy.hm919111.workers.dev\",\r\n            fea