agerCount ? ''eager'' : ''lazy'';\r\n                var gimg = buildGridCardImgAttrs(p.thumbnail);\r\n                return `\r\n                <a href=\"#p?sku=${p.sku}\" class=\"product-card group block animate-fade-in\">\r\n                    <div class=\"product-image-container relative\" style=\"background-color: #ebe6e0;\">\r\n                        ${(() => {\r\n                            if (CONFIG.enableAuraBadge && CONFIG.showAuraBadge && isAuraProduct(p) && !CONFIG.hideAuraTextOnImages) {\r\n                                const bg = CONFIG.auraUseGradient\r\n                                    ? `linear-gradient(90deg, ${escapeHTML(CONFIG.auraPrimaryColor)}, ${escapeHTML(CONFIG.auraSecondaryColor)})`\r\n                                    : `${escapeHTML(CONFIG.auraPrimaryColor)}`;\r\n                                return `<div class=\"absolute top-0 left-0 text-white px-3 py-1.5 text-[9px] font-medium uppercase tracking-[0.2em] z-10\" style=\"background:${bg};\">${escapeHTML(CONFIG.auraBadgeText || ''AURA'')}</div>`;\r\n                            }\r\n                            if (CONFIG.enableSaleBadge && isSaleTag(p)) {\r\n                                return `<div class=\"absolute top-0 left-0 text-white px-3 py-1.5 text-[9px] font-medium uppercase tracking-[0.2em] z-10\" style=\"background-color: var(--os-ink);\">${escapeHTML(CONFIG.saleBadgeText || ''SALE'')}</div>`;\r\n                            }\r\n                            return '''';\r\n                        })()}\r\n                        <img src=\"${gimg.src}\"${gimg.extra} referrerpolicy=\"no-referrer\" loading=\"${loadMode}\" decoding=\"async\" fetchpriority=\"${fetchPr}\" class=\"product-image opacity-100\" data-thumb-alts=\"${encodeURIComponent(JSON.stringify((p.card_images || p.working_images || []).slice(1)))}\" onload=\"handleImageLoad(this)\" onerror=\"handleBrokenImage(this, ''card'')\">\r\n                    </div>\r\n                    <div class=\"pt-3 px-1\