    }\r\n                    } else if (!isFetching && VISIBLE_PRODUCTS.length === 0 && PRODUCTS_DATA.length > 0) {\r\n                        gridHtml = `<div class=\"col-span-full py-16 px-4 text-center text-[11px] leading-relaxed max-w-lg mx-auto\" style=\"color: var(--os-muted);\">No products are visible yet. Check that items are <strong style=\"color:var(--os-ink)\">active</strong>, have <strong style=\"color:var(--os-ink)\">stock &gt; 0</strong>, use a valid <strong style=\"color:var(--os-ink)\">category</strong> (Women, Accessories, …), and that at least one <strong style=\"color:var(--os-ink)\">image URL</strong> loads.</div>`;\r\n                    } else {\r\n                        gridHtml = `<div class=\"col-span-full py-32 text-center text-xs uppercase tracking-widest\" style=\"color: var(--os-muted);\">No items found</div>`;\r\n                    }\r\n                } else if (filtered.length > SHOP_RENDER_LIMIT) {\r\n                    anchorHtml = `<div id=\"scroll-anchor\" class=\"col-span-full h-10 w-full flex items-center justify-center mt-8\"><i data-lucide=\"loader-2\" class=\"w-5 h-5 animate-spin\" style=\"color: #c4bdb4;\"></i></div>`;\r\n                }\r\n\r\n                let pageTitle = ''Catalog'';\r\n                if (cat) pageTitle = escapeHTML(cat);\r\n                else if (tag) pageTitle = escapeHTML(tag);\r\n                else if (search) pageTitle = escapeHTML(search);\r\n\r\n                // Campaign filter buttons (lightweight)\r\n                let campaignFiltersHtml = '''';\r\n                if (CONFIG.enableCampaignFilterButtons && !cat && !search) {\r\n                    const tagsSet = new Set();\r\n                    const tagsNorm = new Set();\r\n                    VISIBLE_PRODUCTS.forEach(function (p) {\r\n                        const t = getCampaignTag(p);\r\n                        if (!t) return;\r\n                        // Month tags are used for background sorting only — never show to custom