    });\r\n                    \r\n                    const preferredSubs = [''Dresses'', ''Tops'', ''Knitwear'', ''Trousers'', ''Skirts'', ''Outerwear'', ''Shorts'', ''Swimwear''];\r\n                    const subList = Array.from(subs).sort((a, b) => {\r\n                        let idxA = preferredSubs.indexOf(a);\r\n                        let idxB = preferredSubs.indexOf(b);\r\n                        if (idxA === -1) idxA = 999;\r\n                        if (idxB === -1) idxB = 999;\r\n                        if (idxA === idxB) return a.localeCompare(b);\r\n                        return idxA - idxB;\r\n                    });\r\n                    \r\n                    if (subList.length > 0) {\r\n                        const encCat = encodeURIComponent(cat);\r\n                        const allClass = !sub ? ''border-b border-black text-black'' : ''hover:text-black'';\r\n                        let pills = `<a href=\"#shop?category=${encCat}\" class=\"${allClass} pb-1 whitespace-nowrap transition-colors\" style=\"${!sub ? ''color: var(--os-ink); border-color: var(--os-ink);'' : ''color: var(--os-muted);''}\">ALL</a>`;\r\n                        \r\n                        subList.forEach(s => {\r\n                            // Hide any subcategory with zero visible items (safety guard).\r\n                            if (!subCounts[s]) return;\r\n                            const isAct = sub && sub.toLowerCase() === s.toLowerCase();\r\n                            const actClass = isAct ? ''border-b border-black text-black'' : ''hover:text-black'';\r\n                            const styleStr = isAct ? ''color: var(--os-ink); border-color: var(--os-ink);'' : ''color: var(--os-muted);'';\r\n                            pills += `<a href=\"#shop?category=${encCat}&sub=${encodeURIComponent(s)}\" class=\"${actClass} pb-1 whitespace-nowrap transition-colors\" style=\"${styleStr}\">${escapeHTML(s.toUpperCase())}</a>`;\r\n                        });\r\n                        \r\n                        subNavHtml = `<div class=\"flex gap-6 overflow-x-auto hide-scroll mb-8 text-[10px] sm:text-[11px] uppercase tracking-[0.15em] font-medium border-b\" style=\"border-color: var(--os-border); padding-bottom: 1rem;\">${pills}</div>`;\r\n                    }\r\n                }\r\n\r\n                contentArea.innerHTML = `\r\n                    <div class=\"px-4 sm:px-6 lg:px-8 py-8 animate-fade-in\">\r\n                        <div class=\"flex flex-col md:flex-row justify-between items-baseline mb-6 ${!subNavHtml ? ''pb-4 border-b'' : ''''}\" style=\"${!subNavHtml ? ''border-color: var(--os-border);'' : ''''}\">\r\n                            <h1 class=\"text-2xl sm:text-3xl font-display font-normal tracking-wide uppercase\">${pageTitle}</h1>\r\n                            <div class=\"relative w-full md:w-64 mt-6 md:mt-0\">\r\n                                <input type=\"text\" id=\"searchInput\" placeholder=\"Search...\" class=\"w-full py-2 border-b outline-none text-xs bg-transparent uppercase tracking-widest\" style=\"border-color: var(--os-border); color: var(--os-ink);\" value=\"${escapeHTML(search) || ''''}\">\r\n                                <i data-lucide=\"search\" class=\"w-4 h-4 absolute right-0 top-2\" style=\"color: #c4bdb4;\"></i>\r\n                            </div>\r\n                        </div>\r\n                        ${campaignFiltersHtml}\r\n                        ${subNavHtml}\r\n                        <div id=\"product-grid\" class=\"grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-x-3 gap-y-10 sm:gap-x-6 lg:gap-x-8\">\r\n                            ${gridHtml}\r\n                        </div>\r\n                        ${anchorHtml}\r\n                    </div>`;\r\n                \r\n                if(window.lucide) window.lucide.createIcons();\r\n                revealLoadedImages(contentArea);\r\n                \r\n                const s = document.getElementById(''searchInput'');\r\n                if (s) {\r\n                    s.addEventListener(''keypress'', e => { \r\n                        if (e.key === ''Enter'') window.location.hash = e.target.value ? `#shop?search=${encodeURIComponent(e.target.value)}` : ''#shop''; \r\n                    });\r\n                }\r\n\r\n                window.scrollTo(0, 0);\r\n                setupIntersectionObserver();\r\n                try {\r\n                    var preSlice = filtered.slice(0, 8);\r\n                    for (var pxi = 0; pxi < preSlice.length; pxi++) {\r\n                        var tu = preSlice[pxi] && preSlice[pxi].thumbnail ? String(preSlice[pxi].thumbnail).trim() : '''';\r\n                        if (tu) injectImagePreload(tu);\r\n                    }\r\n                } catch (ePre) { /* ignore */ }\r\n                scheduleIdleCatalogImagePrefetch(filtered, 8);\r\n            } else {\r\n                const grid = document.getElementById(''product-grid'');\r\n                if (grid) {\r\n                    grid.insertAdjacentHTML(''beforeend'', html);\r\n                    revealLoadedImages(grid);\r\n                    \r\n                    if (filtered.length <= SHOP_RENDER_LIMIT) {\r\n                        const anchor = document.getElementById(''scroll-anchor'');\r\n                        if (anchor) anchor.remove();\r\n                    } else {\r\n                        setupIntersectionObserver();\r\n                    }\r\n                }\r\n                scheduleIdleCatalogImagePrefetch(filtered, startIndex);\r\n            }\r\n        };\r\n\r\n        function normalizeGalleryUrls(urls) {\r\n            const input = Array.isArray(urls) ? urls : [];\r\n            const out = [];\r\n            const seen = new Set();\r\n            for (let i = 0; i < input.length; i++) {\r\n                const u = input[i];\r\n                if (!u || typeof u !== ''string'') continue;\r\n                const s = u.trim();\r\n                if (!s) continue;\r\n                if (seen.has(s)) continue;\r\n                seen.add(s);\r\n                out.push(s);\r\n            }\r\n            // Never render a wall of placeholders.\r\n            const nonFallback = out.filter(function (u) { return u !== FALLBACK_IMAGE; });\r\n            const finalList = nonFallback.length ? nonFallback : out;\r\n            if (!finalList.length) return [FALLBACK_IMAGE];\r\n            return finalList.slice(0, 8);\r\n        }\r\n\r\n        function renderProductGallery(urls) {\r\n            currentGalleryImages = normalizeGalleryUrls(urls);\r\n            const gallery = document.getElementById(''product-gallery'');\r\n            if (!gallery) return;\r\n            const imgsHTML = currentGalleryImages.map(function (img, index) {\r\n                const loadMode = index === 0 ? ''eager'' : ''lazy'';\r\n                return `<div class=\"w-full aspect-[3/4] flex-shrink-0 snap-center cursor-zoom-in relative\" style=\"background-color: #ebe6e0;\" onclick=\"openLightbox(${index})\">\r\n                    <img src=\"${escapeHTML(img)}\" referrerpolicy=\"no-referrer\" loading=\"${loadMode}\" decoding=\"async\" class=\"w-full h-full object-cover opacity-100 absolute inset-0\" onload=\"handleImageLoad(this)\" onerror=\"handleBrokenImage(this, ''gallery'')\">\r\n                </div>`;\r\n            }).join('''');\r\n            gallery.innerHTML = imgsHTML;\r\n            revealLoadedImages(gallery);\r\n        }\r\n\r\n        function mountProductDetailPage(p, probingResultUrls) {\r\n            currentImageIndex = 0;\r\n            isZoomed = false;\r\n            const galleryUrls = normalizeGalleryUrls(probingResultUrls && probingResultUrls.length ? probingResultUrls : []);\r\n            currentGalleryImages = galleryUrls.slice();\r\n            var thumbForCart = galleryUrls[0];\r\n\r\n            const imgsHTML = currentGalleryImages.map(function (img, index) {\r\n                const loa