         </a>`;\r\n                            }).join('''');\r\n                            return `<div class=\"grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-x-3 gap-y-10 sm:gap-x-6 lg:gap-x-8\">${cards}</div>`;\r\n                        })()}\r\n                    </div>\r\n                </div>`;\r\n\r\n            contentArea.innerHTML = html;\r\n            if (window.lucide) window.lucide.createIcons();\r\n            revealLoadedImages(contentArea);\r\n            window.scrollTo(0, 0);\r\n            try {\r\n                var apre = VISIBLE_PRODUCTS.slice(0, 8);\r\n                for (var ai = 0; ai < apre.length; ai++) {\r\n                    var atu = apre[ai] && apre[ai].thumbnail ? String(apre[ai].thumbnail).trim() : '''';\r\n                    if (atu) injectImagePreload(atu);\r\n                }\r\n            } catch (eApre) { /* ignore */ }\r\n            // restore\r\n            VISIBLE_PRODUCTS = oldVisible;\r\n        };\r\n\r\n        const renderCart = () => {\r\n            if (!contentArea) return;\r\n\r\n            if (cart.length === 0) { \r\n                contentArea.innerHTML = `\r\n                    <div class=\"px-4 py-32 text-center animate-fade-in flex flex-col items-center\">\r\n                        <i data-lucide=\"shopping-bag\" class=\"w-16 h-16 mb-8\" style=\"color: #e8e3dc;\"></i>\r\n                        <h1 class=\"text-xl font-display font-normal mb-8 uppercase tracking-wide\" style=\"color: var(--os-ink);\">Your bag is empty</h1>\r\n                        <a href=\"#shop\" class=\"os-btn-primary px-12 py-4 text-[10px] font-semibold uppercase tracking-[0.2em]\">Start shopping</a>\r\n                    </div>`; \r\n                if(window.lucide) window.lucide.createIcons(); \r\n                window.scrollTo(0, 0);\r\n                return; \r\n            }\r\n\r\n            const total = cart.reduce((s, i) => s + (i.price * (i.qty || 1)), 0);\r\n            const items = cart.map((i, idx) => `\r\n                <div class=\"flex py-8 border-b\" style=\"border-color: var(--os-border);\">\r\n                    <div class=\"h-28 w-20 flex-shrink-0 animate-pulse relative\" style=\"background-color: #ebe6e0;\">\r\n                        <img src=\"${escapeHTML(i.image)}\" class=\"h-full w-full object-cover opacity-100 absolute inset-0\" onload=\"handleImageLoad(this)\" onerror=\"handleBrokenImage(this, ''cart'')\">\r\n                    </div>\r\n                    <div class=\"ml-6 flex flex-1 flex-col justify-between\">\r\n                        <div>\r\n                            <div class=\"flex justify-between text-[11px] sm:text-xs font-medium uppercase tracking-wider mb-1\" style=\"color: var(--os-ink);\">\r\n                                <h3 class=\"pr-4\">${escapeHTML(i.name)}</h3>\r\n                                <span>${formatPrice(i.price * (i.qty || 1))}</span>\r\n                            </div>\r\n                            <p class=\"text-[9px] uppercase tracking-widest\" style=\"color: var(--os-muted);\">Size: ${escapeHTML(i.size)}</p>\r\n                        </div>\r\n                        <div class=\"flex items-end justify-between\">\r\n                            <div class=\"flex items-center border rounded-none\" style=\"border-color: var(--os-border); background-color: rgba(255,255,255,0.6);\">\r\n                                <button class=\"px-3 py-1.5\" style=\"color: var(--os-muted);\" onclick=\"updateQty(${idx}, -1)\">-</button>\r\n                                <span class=\"px-2 font-medium text-[10px]\" style=\"color: var(--os-ink);\">${i.qty || 1}</span>\r\n                                <button class=\"px-3 py-1.5\" style=\"color: var(--os-muted);\" onclick=\"updateQty(${idx}, 1)\">+</button>\r\n                            </div>\r\n                            <button class=\"text-[9px] uppercase tracking-widest font-semibold pb-1 hover:opacity-70\" style=\"color: #b0aaa4;\" onclick=\"removeItem(${idx})\">Remove</button>\r\n                        </div>\r\n                    </div>\r\n                </div>`).join('''');\r\n\r\n            contentArea.innerHTML = `\r\n                <div class=\"px-4 sm:px-6 lg:px-8 py-10 max-w-5xl mx-auto animate-fade-in pb-32\">\r\n                    <h1 class=\"text-2xl sm:text-3xl font-display font-normal mb-10 tracking-wide uppercase text-center sm:text-left\" style=\"color: var(--os-ink);\">Your bag</h1>\r\n                    <div class=\"flex flex-col lg:flex-row gap-12\">\r\n                        <div class=\"lg:w-2/3 border-t\" style=\"border-color: var(--os-border);\">${items}</div>\r\n                        <div class=\"lg:w-1/3\">\r\n                            <div class=\"p-8 sticky top-24 rounded-none border\" style=\"background-color: var(--os-surface); border-color: var(--os-border);\">\r\n                                ${CONFIG.cartStoreName ? `\r\n                                <div class=\"mb-5 pb-4 border-b\" style=\"border-color: var(--os-border);\">\r\n                                    <p class=\"text-[9px] uppercase tracking-[0.2em] font-semibold\" style=\"color: var(--os-muted);\">Store</p>\r\n                                    <p class=\"mt-1 text-[11px] uppercase tracking-wider font-medium\" style=\"color: var(--os-ink);\">${escapeHTML(CONFIG.cartStoreName)}</p>\r\n                                </div>\r\n                                ` : ''''}\r\n                                <h2 class=\"text-[10px] font-semibold mb-6 uppercase tracking-widest\" style=\"color: var(--os-muted);\">Order summary</h2>\r\n                                <div class=\"flex justify-between mb-8 pb-4 border-b text-xs font-medium uppercase tracking-widest\" style=\"border-color: var(--os-border); color: var(--os-ink);\">\r\n                                    <dt>Total</dt>\r\n                                    <dd>${formatPrice(total)}</dd>\r\n                                </div>\r\n                                ${(CONFIG.enableTermsAndConditions && CONFIG.termsAndConditionsText) ? `\r\n                                <div class=\"mb-4 text-[10px] leading-relaxed uppercase tracking-widest\" style=\"color: var(--os-muted);\">\r\n                                    <span style=\"color: var(--os-ink); font-weight: 600;\">Terms</span><br>\r\n                                    ${escapeHTML(CONFIG.termsAndConditionsText)}\r\n                                </div>` : ''''}\r\n                                ${(CONFIG.enableFreeDeliveryMessage && CONFIG.freeDeliveryMessage) ? `\r\n                                <div class=\"mb-4 text-[10px] leading-relaxed uppercase tracking-widest\" style=\"color: var(--os-muted);\">\r\n                                    ${escapeHTML(CONFIG.freeDeliveryMessage)}\r\n                                </div>` : ''''}\r\n                                ${(CONFIG.enableCheckoutNote && CONFIG.checkoutNoteText) ? `\r\n                                <div class=\"mb-6 text-[10px] leading-relaxed uppercase tracking-widest\" style=\"color: var(--os-muted);\">\r\n                                    ${escapeHTML(CONFIG.checkoutNoteText)}\r\n                                </div>` : ''''}\r\n                                <div class=\"space-y-4\">\r\n                                    ${CONFIG.enableWhatsAppOrder ? `\r\n                                    <a id=\"whatsapp-btn\" href=\"#\" target=\"_blank\" onclick=\"completeCheckout()\" class=\"w-full bg-[#25D366] text-white py-4 rounded-none flex justify-center items-center space-x-3 font-semibold uppercase tracking-[0.2em] text-[10px] hover:bg-[#128C7E] shadow-lg\">\r\n                                        <i data-lucide=\"message-circle\" class=\"w-4 h-4\"></i>\r\n                                        <span>Checkout via WhatsApp</span>\r\n                                    </a>\r\n                                    ` : ''''}\r\n                                    <button id=\"copy-btn\" class=\"w-full py-4 rounded-none flex justify-center items-center space-x-3 font-semibold uppercase tracking-[0.2em] text-[10px] border\" style=\"background-color: var(--os-surface); border-color: var(--os-border); color: var(--os-ink);\">\r\n                                        <i data-lucide=\"copy\" class=\"w-4 h-4\" style=\"color: var(--os-muted);\"></i>\r\n                                        <span>Copy details</span>\r\n                                    </button>\r\n                                </div>\r\n                                <p class=\"mt-6 text-[8px] text-center uppercase tracking-widest leading-relaxed\" style=\"color: var(--os-muted);\">Shipping and taxes calculated during checkout</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>`;\r\n            if(window.lucide) window.lucide.createIcons();\r\n            revealLoadedImages(contentArea);\r\n\r\n            const waBtn = document.getElementById(''whatsapp-btn'');\r\n            if (waBtn) {\r\n                const message = encodeURIComponent(generateText(total));\r\n                waBtn.href = `https://api.whatsapp.com/send?phone=${CONFIG.whatsappNumber}&text=${message}`;\r\n            }\r\n\r\n            const copyBtn = document.getElementById(''copy-btn'');\r\n            if (copyBtn) {\r\n                copyBtn.addEventListener(''click'', () => {\r\n                    const t = document.createElement(\"textarea\"); t.value = generateText(total); document.body.appendChild(t); t.select(); document.execCommand(''copy''); document.body.removeChild(t);\r\n                    showToast(\"Copied to clipboard\");\r\n                    completeCheckout(); \r\n                });\r\n            }\r\n            \r\n            window.scrollTo(0, 0);\r\n        };\r\n\r\n        window.updateQty = (idx, d) => { if (cart[idx] && cart[idx].qty + d > 0) cart[idx].qty += d; saveCart(); renderCart(); };\r\n        window.removeItem = (idx) => { cart.splice(idx, 1); saveCart(); renderCart(); };\r\n\r\n        const generateText = (tot) => {\r\n            let t = `Hello, I want to order from ${CONFIG.brandName}:\\n\\n`;\r\n            cart.forEach((i, idx) => t += `${idx + 1}) ${i.name} (Art: ${i.sku})\\n   Size ${i.size}\\n   Qty ${i.qty}\\n   Price ${CONFIG.currency} ${i.price}\\n\\n`);\r\n            t += `Total: ${formatPrice(tot)}`; return t;\r\n        };\r\n\r\n        const router = () => {\r\n            try {\r\n                isLoadingMore = false; \r\n                const hash = window.location.hash || '''';\r\n                if (!hash.startsWith(''#p'')) {\r\n                    pdpRenderGeneration++;\r\n                    lastPdpSkuRendered = null;\r\n                    if (pdpDetailAbort) {\r\n                        try { pdpDetailAbort.abort(); } catch (eAbort) {}\r\n                        pdpDetailAbort = null;\r\n                    }\r\n                    try { closeLightbox(); } catch (eLb2) {}\r\n                }\r\n                if (hash === '''' || hash === ''#'') renderHome();\r\n                else if (hash.startsWith(''#shop'')) {\r\n                    const params = new URLSearchParams(hash.split(''?'')[1]);\r\n                    renderShop(params.get(''category''), params.get(''search''), false, params.get(''tag''), params.get(''sub''));\r\n                } else if (hash.startsWith(''#p'')) {\r\n                    const params = new URLSearchParams(hash.split(''?'')[1]);\r\n                    renderProduct(params.get(''sku''));\r\n                } else if (hash === ''#aura'') {\r\n                    renderAura();\r\n                } else if (hash === ''#cart'') renderCart();\r\n                else renderHome();\r\n                \r\n                updateCartBadge();\r\n            } catch (e) {\r\n                console.error(\"Router error:\", e);\r\n            }\r\n        };\r\n\r\n        window.addEventListener(''hashchange'', router);\r\n\r\n        const initApp = () => {\r\n            try {\r\n                loadProducts();\r\n            } catch (e) {\r\n                console.error(e);\r\n                router();\r\n            }\r\n        };\r\n\r\n        if (document.readyState === ''loading'') document.addEventListener(''DOMContentLoaded'', initApp);\r\n        else initApp(); \r\n    </script>\r\n</body>\r\n</html>\r\n","allowScripts":true}', updated_at = CURRENT_TIMESTAMP
